 Syntax Error? (Assumed diagram type: sequence)

@startuml
!theme plain
skinparam backgroundColor #FEFEFE

title Πλήρης ροή καταγραφής σε λειτουργικούς τεστς
actor &quot;Πρόγραμματιστής&quot; as dev
participant &quot;JUnit&quot; as junit
participant &quot;TestClass&quot; as test
participant &quot;Καταγραφέας
(SLF4J)&quot; as logger
participant &quot;Logback&quot; as logback
participant &quot;GradleRunner&quot; as runner
participant &quot;Κονσόλα/Αρχείο&quot; as output

dev -&amp;gt; junit : lance les tests

activate junit
junit -&amp;gt; test : charge la classe
activate test

test -&amp;gt; logger : initialize (companion)
activate logger
logger -&amp;gt; logback : configure
activate logback
logback --&amp;gt; logger : ready
deactivate logback
logger --&amp;gt; test : ✓
deactivate logger

== Phase de Setup ==

junit -&amp;gt; test : @BeforeAll
test -&amp;gt; logger : info(&quot;Αρχικοποίηση&quot;)
logger -&amp;gt; output : [INFO] Initialisation

junit -&amp;gt; test : @BeforeEach
test -&amp;gt; logger : debug(&quot;Δοκιμή ρύθμισης&quot;)
logger -&amp;gt; output : [DEBUG] Setup test

== Phase de Test ==

junit -&amp;gt; test : @Test
test -&amp;gt; logger : info(&quot;ξεκινούντας&quot;)
logger -&amp;gt; output : [INFO] TEST: Starting

test -&amp;gt; runner : create()
activate runner

test -&amp;gt; runner : .forwardOutput()
test -&amp;gt; runner : .build()

runner -&amp;gt; runner : execute Gradle
runner --&amp;gt; test : BuildResult + output text
deactivate runner

test -&amp;gt; logger : debug(&quot;Ανάλυση εξόδου&quot;)
logger -&amp;gt; output : [DEBUG] Analyzing output

test -&amp;gt; test : assertions
test -&amp;gt; logger : info(&quot;✓ Δοκιμή επιτυχής&quot;)
logger -&amp;gt; output : [INFO] ✓ Test passed

== Phase de Cleanup ==

junit -&amp;gt; test : @AfterEach
test -&amp;gt; logger : debug(&quot;Καθαρισμός&quot;)
logger -&amp;gt; output : [DEBUG] Cleanup

junit -&amp;gt; test : @AfterAll
test -&amp;gt; logger : info(&quot;Τέλος των δοκιμών&quot;)
logger -&amp;gt; output : [INFO] Fin des tests

test --&amp;gt; junit : ✓ all tests passed
deactivate test
deactivate junit

dev &amp;lt;-- junit : rapport de tests

@enduml&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_παγίδες_που_πρέπει_να_αποφύγετε&quot;&gt;Παγίδες που πρέπει να αποφύγετε&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_παγίδα_1_να_ξεχάσετε_το_forwardoutput&quot;&gt;�❌ Παγίδα #1: Να ξεχάσετε το `.forwardOutput()&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// MAUVAIS: La sortie Gradle n&#39;est pas capturée
val result = GradleRunner.create()
    .withArguments(&quot;task&quot;)
    .build()

// result.output sera vide !&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// BON: La sortie est capturée
val result = GradleRunner.create()
    .forwardOutput() // ✓
    .withArguments(&quot;task&quot;)
    .build()&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_πίεγμα_n2_μη_αρχικοποιημένος_logger&quot;&gt;❌ Πίεγμα n°2 : Μη αρχικοποιημένος Logger&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// MAUVAIS
class Test {
    lateinit var logger: Logger // Peut ne pas être initialisé
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// BON
class Test {
    companion object {
        private val logger = LoggerFactory.getLogger(...) // Toujours initialisé
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_παγίδα_3_υπerezό_καταγραφή&quot;&gt;❌ Παγίδα №3: Υπerezό Καταγραφή&lt;/h3&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// MAUVAIS: Trop de logs DEBUG en production
logger.debug(&quot;Variable a = $a&quot;)
logger.debug(&quot;Variable b = $b&quot;)
logger.debug(&quot;Variable c = $c&quot;)
// ... 100 lignes de logs&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlightjs highlight&quot;&gt;&lt;code class=&quot;language-kotlin hljs&quot; data-lang=&quot;kotlin&quot;&gt;// BON: Logging ciblé
logger.info(&quot;Traitement de ${items.size} éléments&quot;)
logger.debug(&quot;Détails: ${items.take(5)}...&quot;) // Échantillon seulement&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_αποτελέσματα_και_μετρικές&quot;&gt;Αποτελέσματα και Μετρικές&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Με αυτή τη μέθοδο, θα λάβετε :&lt;/p&gt;
&lt;/div&gt;
&lt;table class=&quot;tableblock frame-all grid-all stretch&quot;&gt;
&lt;colgroup&gt;
&lt;col style=&quot;width: 28.5714%;&quot;&gt;
&lt;col style=&quot;width: 42.8571%;&quot;&gt;
&lt;col style=&quot;width: 28.5715%;&quot;&gt;
&lt;/colgroup&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;Μετρική&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;πριν&lt;/th&gt;
&lt;th class=&quot;tableblock halign-left valign-top&quot;&gt;Μετά&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Γραμμές κώδικα&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;~50 γραμμές&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;~80 γραμμές (+60%)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Χρόνος αποσφαλμάτωσης&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;~30 min&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;~5 λεπτ. (-83%)&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Ανιχνευμένα σφάλματα&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Βασικό&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Λεπτομερής&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Συντήρηση&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Δύσκολος&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;απλό&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;Ανεξαρτησία&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;�❌ συνδεδεμένη&lt;/p&gt;&lt;/td&gt;
&lt;td class=&quot;tableblock halign-left valign-top&quot;&gt;&lt;p class=&quot;tableblock&quot;&gt;✓ ανεξάρτητη&lt;/p&gt;&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_συμπέρασμα&quot;&gt;Συμπέρασμα&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Η ρύθμιση ενός ισχυρού συστήματος καταγραφής στα λειτουργικά δοκίμια των προσθηκών Gradle βασίζεται σε έναν απλό αρχή:&lt;strong&gt;η ανεξαρτησία&lt;/strong&gt;.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Βασικά σημεία που πρέπει να θυμάσαι:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;olist arabic&quot;&gt;
&lt;ol class=&quot;arabic&quot;&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Logger ανεξάρτητος&lt;/strong&gt;: Αρχικοποιημένο σε ένα`companion object`&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;SLF4J + Logback&lt;/strong&gt;: Stack ελεγμένη και ρυθμιζόμενη&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;.forwardOutput()&lt;/strong&gt;: Απολψη της εξόδου του Gradle&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Καταγραφή δομημένη&lt;/strong&gt;INFO για τα βήματα, DEBUG για τα λεπτομέρειες&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;Ανάλυση εξόδου&lt;/strong&gt;: Εξαγωγή πληροφοριών από`result.output`&lt;/p&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Αυτή η προσέγγιση εξασφαλίζει τα τεστ&lt;strong&gt;συντήρησιμα&lt;/strong&gt;, &lt;strong&gt;αποσφαλμαστικά&lt;/strong&gt; et &lt;strong&gt;ισχυροί&lt;/strong&gt;, σε συμμόρφωση με τις στερεές αρχές σχεδιασμού.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_πόροι&quot;&gt;Πόροι&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.gradle.org/current/userguide/test_kit.html&quot;&gt;Τεκμηρίωση Gradle TestKit&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://www.slf4j.org/manual.html&quot;&gt;Εγχειρίδιο SLF4J&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://logback.qos.ch/manual/configuration.html&quot;&gt;Ρύθμιση Logback&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://github.com/gradle/gradle/tree/master/subprojects/test-kit&quot;&gt;Gradle TestKit Πηγαίος κώδικας&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_πήγαινε_περαιτέρω&quot;&gt;Πήγαινε περαιτέρω&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Σε ένα επόμενο άρθρο, θα εξερευνήσουμε :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Συνεχής ενσωμάτωση με δομημένο logging&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Τα HTML αναφορές δοκιμών με ενσωματωμένα logs&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Προχωρημένο debugging με τη σύνδεση JVM&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Οι επιδόσεις και βελτιστοποιήσεις του logging&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;em&gt;Aυτό το άρθρο είναι μέρος της σειράς &quot;Ανάπτυξη προσθηκών Gradle&quot; στο τεχνολογικό μου blog.&lt;/em&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

