άβαρη κλάση Exec { \+ commandLine(args: String...) \+ exec() }

αφηρετική κλάση OpenTestReportTask εκτείνει DefaultTask { \+ group: String = &quot;επαλήθευση \+ περιγραφή: Συμβολο sequência? Wait I wrote Σ? Let&#39;s correct: &quot;Συμβολοσειρά&quot;

Final:
&amp;lt;/think&amp;gt;
\+ περιγραφή: Συμβολοσειρά \+ dependsOn(&quot;check&quot;) \+ συνοψη reportPath: String \+ openReport() : void }

αφηρημένη κλάση AbstractJbakeExecTask επέκταση Exec { + ομάδα: String = &quot;επαλήθευση \+ description: String \+ dependsOn(&quot;check&quot;) + abstract reportRelativePath: String \+ exec() : κενό }

class ReportUnitTestsTask extends OpenTestReportTask { \+ reportPath: String = &quot;build/reports/tests/test/index.html }

κλάση ReportFunctionalTestsTask επεκτείνει OpenTestReportTask { \+ reportPath: String = &quot;build/reports/tests/functionalTest/index.html }

